mapper.insert:
/** [sql-cigmaInterface.xml] CigmaInterfaceMapper.insertDmes18 **/
SELECT COALESCE(MAX(CHLSEQ)+1,1) AS CHLSEQ FROM DMES_18 WHERE CHLLOT = #{st02Lot} AND CHLRTG ='I'
INSERT INTO DMES_18 ( CHLLOT , CHLRTG , CHLDTS , CHLLIN , CHLHOU , CHLPNS , CHLQYS , CHLIDS , CHLSEQ , CRTDT , CRTTM , CRTID , QR_CODE ) VALUES ( #{st02Lot} , 'I' , TO_CHAR(SYSDATE, 'YYYYMMDD') , #{line} , '1' , #{st02Code} , #{st02Moq} , 'LOTMGR' , #{chlseq} , TO_NUMBER(TO_CHAR(SYSDATE,'YYYYMMDD')) , TO_NUMBER(TO_CHAR(SYSDATE,'hh24miss')) , 'LOTMGR' , #{st02Qrcode} )

/** [sql-cigmaInterface.xml] CigmaInterfaceMapper.insertDmes18Output **/
SELECT COALESCE(MAX(CHLSEQ)+1,1) AS CHLSEQ FROM DMES_18 WHERE CHLLOT = #{st03Lot} AND CHLRTG ='I'
INSERT INTO DMES_18 ( CHLLOT , CHLRTG , CHLDTS , CHLLIN , CHLHOU , CHLPNS , CHLQYS , CHLIDS , CHLSEQ , CRTDT , CRTTM , CRTID , QR_CODE ) VALUES ( #{st03Lot} , 'I' , TO_CHAR(SYSDATE, 'YYYYMMDD') , #{st03Line} , '1' , #{st03Code} , #{st03Moq} , 'LOTMGR' , #{chlseq} , TO_NUMBER(TO_CHAR(SYSDATE,'YYYYMMDD')) , TO_NUMBER(TO_CHAR(SYSDATE,'hh24miss')) , 'LOTMGR' , #{st03Qr} )
